    font-size: 15px;
}

.required-indicator {
    color: var(--color-error);
    margin-left: 2px;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 12px 14px;
    border: 2px solid var(--color-border);
    border-radius: 6px;
    background-color: var(--color-input-bg);
    color: var(--color-text-primary);
    font-size: 16px;
