    color: var(--color-text-muted);
}

.help-text {
    font-size: 14px;
    color: var(--color-text-muted);
    line-height: 1.5;
}

.error-message {
    font-size: 14px;
    color: var(--color-error);
    line-height: 1.5;
    min-height: 1.5em;
}

.error-message:empty {
    display: none;
}

.error-message:not(:empty) {
    display: block;
}

.submit-button {
    padding: 12px 24px;
    border: none;
    border-radius: 6px;
    background-color: var(--color-focus);
    color: #ffffff;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s;
    align-self: flex-start;
    margin-top: 8px;
}

.submit-button:hover {
    background-color: #4a8ae8;
}

.submit-button:active {
    background-color: #3a7ad0;
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(90, 159, 255, 0.3);
}

/* Forced Colors mode - button focus ring */
@media (forced-colors: active) {
    .submit-button {
        background-color: ButtonFace;
        color: ButtonText;
        border: 2px solid ButtonBorder;
