+const phoneError = document.getElementById('phone-error');
+
+/**
+ * Validates the full name field.
+ * Returns true if valid, false otherwise.
+ */
+function validateFullName(value) {
+    const trimmed = value.trim();
+    return trimmed.length > 0;
+}
+
+/**
+ * Validates the email field.
+ * Returns true if valid, false otherwise.
+ */
+function validateEmail(value) {
+    const trimmed = value.trim();
+    if (trimmed.length === 0) return false;
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    return emailRegex.test(trimmed);
+}
+
+/**
+ * Validates the phone field (optional, but if provided must be correctly formatted).
+ * Accepts: +1 (555) 123-4567 or (555) 123-4567 or 555-123-4567 or variations.
+ * Returns true if valid or empty, false otherwise.
+ */
+function validatePhone(value) {
+    const trimmed = value.trim();
+    if (trimmed.length === 0) return true;
+
+    const phoneRegex = /^[\d\s\-\+\(\)]+$/.test(trimmed) && trimmed.replace(/\D/g, '').length >= 10;
+    return phoneRegex;
+}
+
+/**
+ * Clears validation state for a field.
+ */
+function clearFieldError(input, errorElement) {
+    input.setAttribute('aria-invalid', 'false');
+    errorElement.textContent = '';
