const fs = require('fs');
const path = require('path');

function analyzeDOM(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];

    // Check for form labels
    const inputs = document.querySelectorAll('input, textarea, select');
    inputs.forEach(input => {
        const id = input.getAttribute('id');
        const label = id ? document.querySelector(`label[for="${id}"]`) : null;

        if (label || input.getAttribute('aria-label')) {
            passes.push({
                id: 'form-field-label',
                description: 'Form field has a label',
                nodes: [{ html: input.outerHTML }]
            });
        } else if (!input.closest('[role="presentation"]')) {
            violations.push({
                id: 'form-field-label',
                description: 'Form field does not have a label',
                impact: 'critical',
                help: 'Add a label to all form fields',
                helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/labels-or-instructions',
                nodes: [{ html: input.outerHTML }]
            });
        }
    });

    // Check for button text
    const buttons = document.querySelectorAll('button');
    buttons.forEach(btn => {
        if (btn.textContent.trim() || btn.getAttribute('aria-label')) {
            passes.push({
                id: 'button-name',
                description: 'Button has descriptive text',
                nodes: [{ html: btn.outerHTML }]
            });
        } else {
            violations.push({
                id: 'button-name',
                description: 'Button does not have accessible name',
                impact: 'critical',
                help: 'Add text or aria-label to buttons',
                helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/name-role-value',
                nodes: [{ html: btn.outerHTML }]
            });
        }
    });

    // Check for required field indicators
    const requiredInputs = document.querySelectorAll('input[required]');
    requiredInputs.forEach(input => {
        const label = document.querySelector(`label[for="${input.id}"]`);
        if (label) {
            // Check if there's a visual indicator (span with aria-hidden)
            const requiredIndicator = label.querySelector('[aria-hidden="true"]');
            if (requiredIndicator || input.hasAttribute('aria-required')) {
                passes.push({
                    id: 'required-field-indicator',
                    description: 'Required field has visual and programmatic marker',
                    nodes: [{ html: label.outerHTML }]
                });
            } else {
                violations.push({
                    id: 'required-field-indicator',
                    description: 'Required field missing visual indicator',
                    impact: 'minor',
                    help: 'Add visual indicator for required fields',
                    helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/labels-or-instructions',
                    nodes: [{ html: label.outerHTML }]
                });
            }
        }
    });

    // Check for page title
    const title = document.querySelector('title');
    if (title && title.textContent.trim()) {
        passes.push({
            id: 'page-title',
            description: 'Page has a title',
            nodes: [{ html: title.outerHTML }]
        });
    } else {
        violations.push({
            id: 'page-title',
            description: 'Page missing title element',
            impact: 'critical',
            help: 'Add a descriptive title to the page',
            helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/page-titled',
            nodes: [{ html: '<title></title>' }]
        });
    }

    // Check for main landmark
    const main = document.querySelector('main');
    if (main) {
        passes.push({
            id: 'landmark-main',
            description: 'Page has a main landmark',
            nodes: [{ html: main.outerHTML.substring(0, 50) + '...' }]
        });
    } else {
        violations.push({
            id: 'landmark-main',
            description: 'Page missing main landmark',
            impact: 'moderate',
            help: 'Wrap main content in a main element',
            helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/page-structure',
            nodes: [{ html: '<body></body>' }]
        });
    }

    // Check for heading hierarchy
    const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
    if (headings.length > 0) {
        const firstHeading = headings[0].tagName;
        if (firstHeading === 'H1') {
            passes.push({
                id: 'heading-hierarchy',
                description: 'Page starts with H1',
                nodes: [{ html: headings[0].outerHTML }]
            });
        } else {
            violations.push({
                id: 'heading-hierarchy',
                description: 'Page does not start with H1',
                impact: 'moderate',
                help: 'Start page with an H1 heading',
                helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/page-structure',
                nodes: [{ html: headings[0].outerHTML }]
            });
        }
    } else {
        violations.push({
            id: 'heading-hierarchy',
            description: 'Page has no headings',
            impact: 'moderate',
            help: 'Add heading structure to the page',
            helpUrl: 'https://www.w3.org/WAI/WCAG21/Understanding/page-structure',
            nodes: [{ html: '<body></body>' }]
        });
    }

    // Check for form validation and aria-invalid/aria-describedby
    const formInputs = document.querySelectorAll('input[type="email"], input[type="tel"], input[required]');
    formInputs.forEach(input => {
        const describedBy = input.getAttribute('aria-describedby');
        if (describedBy) {
            passes.push({
                id: 'form-help-text',
                description: 'Form field has aria-describedby for help/error text',
                nodes: [{ html: input.outerHTML }]
            });
        }
    });

    return { violations, passes, incomplete };
}

async function runAccessibilityTests() {
    // Read the HTML file
    const htmlPath = path.join(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    // Create a virtual DOM
    const dom = new JSDOM(htmlContent, {
        url: 'file://' + htmlPath,
        pretendToBeVisual: true,
        resources: 'usable'
    });

    const { document } = dom.window;
    return analyzeDOM(document);
}

